test_that("use_favicon_dsfr works", {
  tp <- tempdir()
  app <- file.path(tp, "app")
  dir.create(app)
  message("debug 1. le dossier app cree pour le test se trouve a : \n ", app)
  # version shiny basique (le seul test pour l'instant)
  path_fav_shiny_base <- file.path(tp, "app", "www", "favicon.ico")
  message("debug 2. la favicon doit etre cree par `use_favicon_dsfr()` a : \n ", path_fav_shiny_base)
  use_favicon_dsfr(path_app = app, golem_app = FALSE)
  message("debug 3. contenu du dossier 'app' : \n ", paste(list.files(path = app, all.files = TRUE, full.names = TRUE, recursive = TRUE, include.dirs = TRUE), collapse = " \n "))
  message("debug 4. contenu du dossier 'temp' : \n ", paste(list.files(path = tp, all.files = TRUE, full.names = TRUE, recursive = TRUE, include.dirs = TRUE), collapse = " \n "))
  path_favicon_shingouv <- system.file(paste0("dsfr-v", get_dsfr_version(), "/dist/favicon/favicon.ico"), package = "shinygouv")
  message("debug 5. localisation de l'icone de shinygouv dans le contexte du test  : \n ", path_favicon_shingouv)
  file.copy(from = path_favicon_shingouv, to = path_fav_shiny_base, overwrite = TRUE, recursive = FALSE)

  expect_true(file.exists(path_fav_shiny_base))
  })
